param(
    [string]$ProjectRoot = "E:\MY PROJECT FOLDER\AURA PROJECT\AURA-Butler-Android-Studio-v0.4.0-Native-Stable",
    [switch]$SkipBuild
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

Write-Host "============================================================" -ForegroundColor Cyan
Write-Host "AURA Voice Timing Diagnostics" -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host "Project: $ProjectRoot"
Write-Host ""
Write-Host "Adds real on-device timing for:" -ForegroundColor Yellow
Write-Host " - AI reply generation latency"
Write-Host " - TTS request -> actual voice start"
Write-Host " - actual speaking duration"
Write-Host " - total AI + voice time"
Write-Host " - Piper model load, synthesis and generated-audio duration"
Write-Host " - a live 'Last voice timing' card in AURA Settings"
Write-Host ""
Write-Host "No speech text or microphone audio is stored by the timing logger."
Write-Host ""

$AndroidRoot = Join-Path $ProjectRoot "android"
$Gradlew = Join-Path $AndroidRoot "gradlew.bat"

if (-not (Test-Path -LiteralPath $AndroidRoot)) {
    throw "Android project not found: $AndroidRoot"
}

$Manifest = @(
    [pscustomobject]@{ RelativePath='android\app\src\main\java\in\diganta\aurabutler\ButlerViewModel.kt'; Expected='FEB779D90F4DF8342E9B2536F17FBA9BAFE716F04A1AF39A04DFB0387A51D4B7'; Target='E387FE8B9C08ED9C9AAE96C77A579D49DA2B2747609A69256132237AE72682DC'; AllowMissing=$false; Base64='' },
    [pscustomobject]@{ RelativePath='android\app\src\main\java\in\diganta\aurabutler\ui\AuraApp.kt'; Expected='A74B8511E832D76C669CF4905034DEC73CCA13210F025F363ECC6F2384F08517'; Target='1AA325177CA09F2FF25CCF0C42F66D395E3CBDE1B7C0CA31D96E224957B28A32'; AllowMissing=$false; Base64='' },
    [pscustomobject]@{ RelativePath='android\app\src\main\java\in\diganta\aurabutler\voice\Speaker.kt'; Expected='25C267711DC1777FB76AF2933F20F064344AB6B0658832887F28EFABFFA2BE77'; Target='C908C5816F31A9E1376DC744F65A0DA6B7DC1B8F89696D1AF9CB5468B5A1A87D'; AllowMissing=$false; Base64='' },
    [pscustomobject]@{ RelativePath='android\app\src\main\java\in\diganta\aurabutler\voice\FastSystemSpeaker.kt'; Expected='D65449D48936953C4892387ECF13E46282B25347E4E0360DA1864BF6B78ED083'; Target='49D700732619B7D686D45834C4D3D65D83283761534B5D672D6FDB16F0C7334F'; AllowMissing=$false; Base64='' },
    [pscustomobject]@{ RelativePath='android\app\src\main\java\in\diganta\aurabutler\voice\PiperSpeaker.kt'; Expected='56245F0E2552883652DEA68EE9906B6AF34D42B7F5B70DD6E108EA1C1B465454'; Target='3F5EEFC668AB7F8645EADB3FBD41788B58BB27198901C566137E8374A574D194'; AllowMissing=$false; Base64='' },
    [pscustomobject]@{ RelativePath='android\app\src\main\java\in\diganta\aurabutler\voice\VoiceTimingDiagnostics.kt'; Expected=''; Target='684EF28BCF187A7E25874BBFCE51655091CBBCF2BDDA25A05B4774916BE9FF13'; AllowMissing=$true; Base64='' }
)

$BackupRoot = Join-Path $ProjectRoot (".aura-voice-timing-backup\" + (Get-Date -Format "yyyyMMdd-HHmmss"))

Write-Host "==> Compatibility + hash preflight" -ForegroundColor Cyan
$NeedPatch = 0
foreach ($Entry in $Manifest) {
    $Path = Join-Path $ProjectRoot $Entry.RelativePath

    if (-not (Test-Path -LiteralPath $Path)) {
        if ($Entry.AllowMissing) {
            $NeedPatch += 1
            continue
        }
        throw "Required source file is missing: $Path"
    }

    $Hash = (Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash.ToUpperInvariant()
    if ($Hash -eq $Entry.Target) {
        continue
    }
    if ($Entry.AllowMissing -and [string]::IsNullOrWhiteSpace($Entry.Expected)) {
        throw "Unexpected pre-existing file: $Path`nActual SHA256: $Hash"
    }
    if ($Hash -ne $Entry.Expected) {
        throw @"
Refusing to overwrite an unexpected source file:
$Path

Expected current SHA256:
$($Entry.Expected)

Target timing-instrumented SHA256:
$($Entry.Target)

Actual SHA256:
$Hash

This timing patch is designed for the current AURA v0.15.x voice/UI sources.
Send the actual hash for review instead of forcing it.
"@
    }

    $NeedPatch += 1
}
Write-Host "PASS: compatibility preflight; $NeedPatch file(s) require patching" -ForegroundColor Green

Write-Host ""
Write-Host "==> Installing voice timing diagnostics" -ForegroundColor Cyan
foreach ($Entry in $Manifest) {
    $Path = Join-Path $ProjectRoot $Entry.RelativePath

    if (Test-Path -LiteralPath $Path) {
        $Hash = (Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash.ToUpperInvariant()
        if ($Hash -eq $Entry.Target) {
            Write-Host "CURRENT: $($Entry.RelativePath)"
            continue
        }

        $BackupPath = Join-Path $BackupRoot $Entry.RelativePath
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $BackupPath) | Out-Null
        Copy-Item -LiteralPath $Path -Destination $BackupPath -Force
    }
    else {
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $Path) | Out-Null
    }

    $Bytes = [Convert]::FromBase64String($Entry.Base64)
    [IO.File]::WriteAllBytes($Path, $Bytes)

    $After = (Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash.ToUpperInvariant()
    if ($After -ne $Entry.Target) {
        throw "Write verification failed for $($Entry.RelativePath)"
    }
    Write-Host "PATCHED: $($Entry.RelativePath)" -ForegroundColor Green
}

$TimingFile = Join-Path $ProjectRoot "android\app\src\main\java\in\diganta\aurabutler\voice\VoiceTimingDiagnostics.kt"
$SpeakerFile = Join-Path $ProjectRoot "android\app\src\main\java\in\diganta\aurabutler\voice\Speaker.kt"
$FastFile = Join-Path $ProjectRoot "android\app\src\main\java\in\diganta\aurabutler\voice\FastSystemSpeaker.kt"
$PiperFile = Join-Path $ProjectRoot "android\app\src\main\java\in\diganta\aurabutler\voice\PiperSpeaker.kt"
$UiFile = Join-Path $ProjectRoot "android\app\src\main\java\in\diganta\aurabutler\ui\AuraApp.kt"
$VmFile = Join-Path $ProjectRoot "android\app\src\main\java\in\diganta\aurabutler\ButlerViewModel.kt"

$Checks = @(
    @{ Name="timing diagnostics source"; Pass=(Get-Content -Raw $TimingFile).Contains('object VoiceTimingDiagnostics') },
    @{ Name="AI latency captured"; Pass=(Get-Content -Raw $VmFile).Contains('VoiceTimingDiagnostics.noteAiLatency') },
    @{ Name="foreground Android TTS start/done timing"; Pass=(Get-Content -Raw $SpeakerFile).Contains('UtteranceProgressListener') },
    @{ Name="background Android TTS timing"; Pass=(Get-Content -Raw $FastFile).Contains('"Android TTS background"') },
    @{ Name="Piper model/synthesis/audio timing"; Pass=(Get-Content -Raw $PiperFile).Contains('audioDurationMs') },
    @{ Name="Settings timing card"; Pass=(Get-Content -Raw $UiFile).Contains('"Last voice timing"') }
)
foreach ($Check in $Checks) {
    if (-not $Check.Pass) {
        throw "Static timing validation failed: $($Check.Name)"
    }
    Write-Host "PASS [static]: $($Check.Name)" -ForegroundColor Green
}

if ($SkipBuild) {
    Write-Host ""
    Write-Host "SkipBuild requested. Source is instrumented; APK not rebuilt." -ForegroundColor Yellow
    exit 0
}

if (-not (Test-Path -LiteralPath $Gradlew)) {
    throw "Gradle wrapper not found: $Gradlew"
}

foreach ($Candidate in @(
    "E:\Program Files\Android\Android Studio\jbr",
    "C:\Program Files\Android\Android Studio\jbr"
)) {
    if (Test-Path -LiteralPath (Join-Path $Candidate "bin\java.exe")) {
        $env:JAVA_HOME = $Candidate
        break
    }
}

Write-Host ""
Write-Host "==> Android verification" -ForegroundColor Cyan
Push-Location $AndroidRoot
try {
    & $Gradlew --no-daemon testDebugUnitTest lintDebug assembleDebug
    $GradleExit = $LASTEXITCODE
}
finally {
    Pop-Location
}
if ($GradleExit -ne 0) {
    throw "Gradle verification failed with exit code $GradleExit"
}

$Apk = Join-Path $AndroidRoot "app\build\outputs\apk\debug\app-debug.apk"
if (-not (Test-Path -LiteralPath $Apk)) {
    throw "Gradle succeeded but app-debug.apk was not found."
}

$FinalApk = Join-Path $ProjectRoot "AURA-voice-timing-debug.apk"
Copy-Item -LiteralPath $Apk -Destination $FinalApk -Force

Write-Host ""
Write-Host "============================================================" -ForegroundColor Green
Write-Host "SUCCESS: AURA voice timing diagnostics installed." -ForegroundColor Green
Write-Host "============================================================" -ForegroundColor Green
Write-Host "APK: $FinalApk"
Write-Host ""
Write-Host "Install this APK as an UPDATE."
Write-Host "Then open AURA -> Settings -> Test AURA voice."
Write-Host "Wait until speech finishes. The 'Last voice timing' card will show:"
Write-Host "  AI time | voice-start delay | speaking time | total | character count"
Write-Host "For Piper it also shows model-load, synthesis and generated-audio time."
